{
  "understanding": {
    "purpose": "对照三项指标在年度经营目标、客户满意度提升和研发效能改进三种角色下的内容，突出各指标对应的目标或改进内容。",
    "reading": "先按首列定位指标，再横向查找该行的有效内容；纵向扫描各角色列时，读者可比较对应条目，并快速识别破折号所表示的空项。",
    "groups": [
      "第2至第4列都是角色或目标列，应保持相近的视觉权重；其中第4列内容较长，需要更多宽度。",
      "首列是行标题，与上方列标题共同构成查找路径，需要便于快速辨认。"
    ],
    "keep_intact": [
      "百分比、数字及其单位或符号，例如25%和50。",
      "缩写及其相邻数字，例如NPS和50。",
      "破折号应独立且清晰可见。"
    ],
    "may_wrap": [
      "较长的中文列标题和行标题可在词语边界自然换行。",
      "目标或改进内容中的中文短语可自然换行；若同一行已有较高单元格，其他单元格的换行可利用该行高度。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [110, 111, 119, 139],
      "idea": "均衡行标题与三个角色列，同时按内容长度向第4列倾斜，兼顾横向查找和整体节奏。"
    },
    {
      "name": "B",
      "widths": [143, 100, 107, 129],
      "idea": "优先给行标题完整的一行宽度，强化纵向定位，让角色列中的较长标题和内容承担更多换行。"
    },
    {
      "name": "C",
      "widths": [89, 109, 104, 177],
      "idea": "优先让最长的第4列内容保持一行，压缩首列并允许行标题换行，以突出较长的改进内容。"
    }
  ]
}
